<?php
$active_module = 'properties';
require_once __DIR__ . '/layout.php';
require_once __DIR__ . '/../config/i18n.php';
require_once __DIR__ . '/../config/listing_integrity.php';
require_once __DIR__ . '/../config/platform_settings.php';
require_once __DIR__ . '/../config/feature_lists.php';
$u = $supplier_user;
$id = filter_input(INPUT_GET, 'product', FILTER_VALIDATE_INT);
if (!$id) { header('Location: /nexustraveltech/tedarikci/tesisler'); exit; }
$q = db()->prepare("SELECT * FROM properties WHERE id=? AND supplier_id=? AND property_type IN ('villa','yacht') LIMIT 1");
$q->execute([$id, $u['supplier_id']]);
$listing = $q->fetch();
if (!$listing) { http_response_code(404); exit('Ürün bulunamadı.'); }
$isYacht = $listing['property_type'] === 'yacht';
$unitLabel = $isYacht ? 'Kabin / yat' : 'Konaklama birimi';
$details = json_decode($listing['product_details'] ?? '{}', true) ?: [];
$error = '';
$errorSec = ''; // form gönderimi sonrası yumuşak otomatik kaydırma hedefi (sec-XX)
$notice = isset($_GET['published']) ? 'Ürün yayına alındı — acente müsaitlik sorgularında artık görünür.' : (isset($_GET['saved']) ? 'Detaylar kaydedildi.' : (isset($_GET['room_saved']) ? 'Yeni birim çoğaltıldı; özellik ve fiyatı kaydedildi.' : ''));

// --- Yayına al ---
if ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['action'] ?? '') === 'publish') {
  if (!csrf_valid($_POST['csrf_token'] ?? null)) { $error = 'Güvenlik doğrulaması yenilendi. Lütfen tekrar deneyin.'; }
  else {
    $readiness = listing_readiness($listing);
    if (!$readiness['ready']) {
      $missing = array_map(fn($i) => $i['label'], array_filter($readiness['items'], fn($i) => !$i['ok']));
      $error = 'Ürün yayına alınamadı — eksik kalemler: ' . implode(', ', $missing) . '.';
      $errorSec = (string) (listing_first_missing_section($listing) ?? '');
    } else {
      db()->prepare("UPDATE properties SET status='active' WHERE id=? AND supplier_id=?")->execute([$id, $u['supplier_id']]);
      record_audit_event('supplier', (int) $u['id'], 'publish', 'property', $id, ['name' => $listing['name']]);
      header('Location: /nexustraveltech/tedarikci/villa-detay?product=' . $id . '&published=1'); exit;
    }
  }
}

// --- Birim çoğalt ---
if ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['room_action'] ?? '') === 'duplicate') {
  if (!csrf_valid($_POST['csrf_token'] ?? null)) { $error = 'Güvenlik doğrulaması yenilendi. Lütfen tekrar deneyin.'; }
  else {
    $sourceId = (int)($_POST['room_source_id'] ?? 0);
    $newName = trim((string)($_POST['room_name'] ?? ''));
    $source = db()->prepare('SELECT r.* FROM room_types r WHERE r.id=? AND r.property_id=? LIMIT 1');
    $source->execute([$sourceId, $id]); $source = $source->fetch();
    if (!$source || $newName === '') { $error = 'Çoğaltılacak birim ve yeni ad gereklidir.'; }
    else {
      $roomDetails = json_decode($source['room_details'] ?? '{}', true) ?: [];
      $roomDetails['area_m2'] = max(0, (int)($_POST['room_area'] ?? ($roomDetails['area_m2'] ?? 0)));
      $roomDetails['default_nightly_price'] = max(0, (float)str_replace(',', '.', (string)($_POST['room_price'] ?? ($roomDetails['default_nightly_price'] ?? 0))));
      $roomDetails['price_currency'] = in_array($_POST['room_currency'] ?? 'EUR', ['TRY','EUR','USD','GBP'], true) ? $_POST['room_currency'] : 'EUR';
      $capacity = max(1, min(20, (int)($_POST['room_capacity'] ?? $source['capacity_adults'])));
      $units = max(0, min(9999, (int)($_POST['room_units'] ?? $source['total_units'])));
      db()->prepare('INSERT INTO room_types (property_id,name,capacity_adults,total_units,room_details,status) VALUES (?,?,?,?,?,"active")')->execute([$id,$newName,$capacity,$units,json_encode($roomDetails, JSON_UNESCAPED_UNICODE)]);
      header('Location: /nexustraveltech/tedarikci/villa-detay?product='.$id.'&room_saved=1'); exit;
    }
  }
}

// --- Genel kaydet ---
if ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['room_action'] ?? '') !== 'duplicate' && ($_POST['action'] ?? '') !== 'publish') {
  if (!csrf_valid($_POST['csrf_token'] ?? null)) { $error = 'Güvenlik doğrulaması yenilendi. Lütfen tekrar deneyin.'; }
  else {
    $typeKeys = $isYacht
      ? ['cabins','guest_capacity','length','home_port','crew','year_built']
      : ['bedrooms','max_guests','pool','area_m2','floors','building_type'];
    $textKeys = array_merge(['address','district','area','airport_distance','beach_distance','latitude','longitude','short_description','description','check_in','check_out','pet_policy','smoking_policy','minimum_age','board_notes','commission_rate','deposit_rate','collection_model','account_holder','bank_name','iban','payment_note','free_cancellation_until','cancellation_advance_days','cancellation_fee_rate','no_show_fee_rate','refund_method','refund_processing_days','cancellation_note'], $typeKeys);
    foreach ($textKeys as $key) { $value = trim((string)($_POST['details'][$key] ?? '')); if ($value !== '') $details[$key] = $value; else unset($details[$key]); }
    foreach (['bedrooms','max_guests','area_m2','floors','cabins','guest_capacity','length','year_built'] as $key) {
      if (isset($details[$key])) { $details[$key] = max(0, (int) $details[$key]); if ($details[$key] === 0) unset($details[$key]); }
    }
    if (isset($details['crew'])) { $details['crew'] = trim((string) $details['crew']); if ($details['crew'] === '') unset($details['crew']); }
    $amenityList = property_feature_lists($isYacht ? 'yacht' : 'villa');
    $servicePricing = [];
    foreach (($_POST['service_pricing'] ?? []) as $service => $status) {
      if (in_array($service, $amenityList, true) && in_array($status, ['free', 'paid'], true)) $servicePricing[$service] = $status;
    }
    $details['service_pricing'] = $servicePricing;
    $details['amenities'] = array_values(array_intersect(array_keys($servicePricing), $amenityList));
    $commission = (float)str_replace(',', '.', $details['commission_rate'] ?? '0');
    $deposit = (float)str_replace(',', '.', $details['deposit_rate'] ?? '0');
    $allowedCollectionModels = ['agency_collects_deposit','agency_collects_full','property_collects_full'];
    $details['collection_model'] = $details['collection_model'] ?? 'agency_collects_deposit';
    if ($commission < 0 || $commission > 100 || $deposit < 0 || $deposit > 100 || !in_array($details['collection_model'], $allowedCollectionModels, true)) {
      $error = 'Komisyon, ön ödeme ve tahsilat modeli bilgilerini kontrol edin.';
      $errorSec = 'sec-06';
    }
    $iban = preg_replace('/\s+/', '', strtoupper($details['iban'] ?? ''));
    if ($iban !== '' && !preg_match('/^TR\d{24}$/', $iban)) { $error = 'IBAN, TR ile başlayan 26 karakterlik geçerli bir Türkiye IBAN’ı olmalıdır.'; $errorSec = 'sec-06'; }
    $details['iban'] = $iban;
    foreach (['cancellation_advance_days','cancellation_fee_rate','no_show_fee_rate','refund_processing_days'] as $key) {
      $value = (float)str_replace(',', '.', $details[$key] ?? '0');
      $max = $key === 'cancellation_advance_days' ? 365 : ($key === 'refund_processing_days' ? 60 : 100);
      if ($value < 0 || $value > $max) { $error = 'İptal ve iade oranlarını kontrol edin.'; $errorSec = 'sec-07'; }
    }
    $allowedRefundMethods = ['original_payment','bank_transfer','agency_settlement','voucher'];
    if (($details['refund_method'] ?? '') !== '' && !in_array($details['refund_method'], $allowedRefundMethods, true)) { $error = 'Geçerli bir iade yöntemi seçin.'; $errorSec = 'sec-07'; }
    if ($error === '') {
    try {
      $pdo = db(); $pdo->beginTransaction();
      $pdo->prepare('UPDATE properties SET product_details=? WHERE id=? AND supplier_id=?')->execute([json_encode($details, JSON_UNESCAPED_UNICODE), $id, $u['supplier_id']]);
      if (!empty($_FILES['media']['name'][0])) {
        $allowed = ['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];
        $finfo = new finfo(FILEINFO_MIME_TYPE);
        $dir = dirname(__DIR__) . '/uploads/properties/' . $id;
        if (!is_dir($dir)) mkdir($dir, 0755, true);
        $insert = $pdo->prepare('INSERT INTO property_media (property_id,file_path,file_name,mime_type,is_cover,sort_order) VALUES (?,?,?,?,?,?)');
        foreach ($_FILES['media']['tmp_name'] as $index=>$tmp) {
          if ($_FILES['media']['error'][$index] !== UPLOAD_ERR_OK || $_FILES['media']['size'][$index] > 8*1024*1024) continue;
          $mime = $finfo->file($tmp); if (!isset($allowed[$mime])) continue;
          $filename = bin2hex(random_bytes(12)) . '.' . $allowed[$mime];
          if (move_uploaded_file($tmp, $dir . '/' . $filename)) $insert->execute([$id,'uploads/properties/'.$id.'/'.$filename,basename((string)$_FILES['media']['name'][$index]),$mime,$index===0 ? 1 : 0,$index]);
        }
      }
      $pdo->commit(); header('Location: /nexustraveltech/tedarikci/villa-detay?product='.$id.'&saved=1'); exit;
    } catch (Throwable $e) { if (db()->inTransaction()) db()->rollBack(); $error='Kaydetme sırasında bir sorun oluştu.'; }
    }
  }
}

$media = db()->prepare('SELECT * FROM property_media WHERE property_id=? ORDER BY is_cover DESC, sort_order, id'); $media->execute([$id]); $media=$media->fetchAll();
$rooms = db()->prepare('SELECT * FROM room_types WHERE property_id=? ORDER BY id'); $rooms->execute([$id]); $rooms=$rooms->fetchAll();
$servicePricing = is_array($details['service_pricing'] ?? null) ? $details['service_pricing'] : [];
foreach (($details['amenities'] ?? []) as $service) if (!isset($servicePricing[$service])) $servicePricing[$service] = 'free';
supply_start(htmlspecialchars($listing['name']).' · ilan detayları', $active_module); ?>
<section class="hotel-editor-head"><div><span><?= $isYacht ? 'YAT İLAN KURULUMU' : 'VİLLA İLAN KURULUMU' ?></span><h2>Satış kanallarına eksiksiz<br>ürün verisi gönderin.</h2><p>İlan tamamlanma durumu: <b><?= count($media) ? 'görseller eklendi' : 'görsel bekliyor' ?></b></p></div><a href="/nexustraveltech/tedarikci/tesisler">← Ürün listesine dön</a></section>
<?php $readiness = listing_readiness($listing); $__channelItem = null; $__icalItem = null; foreach ($readiness['items'] as $__ci) { if ($__ci['key'] === 'channel') { $__channelItem = $__ci; } elseif ($__ci['key'] === 'ical') { $__icalItem = $__ci; } } $chLink = '/nexustraveltech/tedarikci/dagitim-merkezi' . ($__channelItem && !empty($__channelItem['first_bad_id']) ? '#channel-retry-' . (int) $__channelItem['first_bad_id'] : ''); $icalLink = '/nexustraveltech/tedarikci/ical-takvimler?property='.$id . ($__icalItem && !empty($__icalItem['first_conn_id']) ? '#sync-' . (int) $__icalItem['first_conn_id'] : '#sync'); $linkFor = ['rooms' => '/nexustraveltech/tedarikci/villa-detay?product='.$id.'#sec-04', 'rates' => '/nexustraveltech/tedarikci/fiyat-kontenjan?property='.$id, 'inventory' => '/nexustraveltech/tedarikci/fiyat-kontenjan?property='.$id, 'media' => '/nexustraveltech/tedarikci/villa-detay?product='.$id.'#sec-05', 'description' => '/nexustraveltech/tedarikci/villa-detay?product='.$id.'#sec-02', 'location' => '/nexustraveltech/tedarikci/villa-detay?product='.$id.'#sec-01', 'pool' => '/nexustraveltech/tedarikci/villa-detay?product='.$id.'#sec-01', 'home_port' => '/nexustraveltech/tedarikci/villa-detay?product='.$id.'#sec-01', 'crew' => '/nexustraveltech/tedarikci/villa-detay?product='.$id.'#sec-01', 'ical' => $icalLink, 'channel' => $chLink, 'rules' => '/nexustraveltech/tedarikci/satis-kurallari?property='.$id]; $linkTooltips = readiness_tooltips(); $secHint = ['rooms' => 'Birim envanteri #sec-04', 'rates' => 'Fiyat & kontenjan', 'inventory' => 'Fiyat & kontenjan', 'media' => 'Görseller #sec-05', 'description' => 'Satış içeriği #sec-02', 'location' => 'Kimlik & konum #sec-01', 'pool' => 'Kimlik & konum #sec-01', 'home_port' => 'Kimlik & konum #sec-01', 'crew' => 'Kimlik & konum #sec-01', 'ical' => 'iCal takvimleri', 'channel' => 'Dağıtım merkezi', 'rules' => 'Satış kuralları']; /* Bölümler tek kaynaktan numaralanır — yeni bölüm eklerken yalnızca bu diziye satır ekle. */ $editorSections = ['Kimlik, sınıflandırma & konum' => 'Kimlik & konum', 'Satış içeriği & operasyon' => 'Satış içeriği', 'Özellikler & hizmetler' => 'Özellikler', $unitLabel.' envanteri & fiyat' => 'Birim & fiyat', 'Görseller' => 'Görseller', 'Acente komisyonu & tahsilat' => 'Komisyon & tahsilat', 'İptal & iade şartları' => 'İptal & iade']; $editorToc = []; $editorN = 0; foreach ($editorSections as $fullTitle => $shortTitle) { $editorN++; $editorToc[] = ['id' => 'sec-'.str_pad((string)$editorN, 2, '0', STR_PAD_LEFT), 'no' => str_pad((string)$editorN, 2, '0', STR_PAD_LEFT), 'title' => $fullTitle, 'short' => $shortTitle]; } $editorN = 0; ?>
<section class="publish-panel"><div class="publish-head"><div><span>YAYINA ALMA AKIŞI</span><h3>Hazırlık kontrol listesi · <b><?= $readiness['score'] ?>/100</b></h3><p>Tüm çekirdek kalemler (villa: havuz, yat: liman + mürettebat, ikisi için de aktif iCal bağlantısı dahil) tamamlandığında ürün tek tıkla yayına alınır; satış kuralı opsiyoneldir.<?php if ($readiness['missing_count'] > 0): ?> <b><?= (int) $readiness['ok_count'] ?> kalem tamam</b> — kalan <b><?= (int) $readiness['missing_count'] ?> kalem</b> tamamlanınca 100 olur.<?php endif; ?></p></div><?php if ($listing['status'] === 'active'): ?><b class="status active-status">YAYINDA</b><?php else: ?><form method="post" class="publish-form"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(csrf_token()) ?>"><input type="hidden" name="action" value="publish"><?php if ($readiness['ready']): ?><button class="primary-button" onclick="return confirm('Ürün yayına alınsın mı? Acente müsaitlik sorgularında görünür olur.');">Yayına al →</button><?php else: ?><span class="ghost-button disabled" title="Eksik kalemler tamamlanmadan yayına alınamaz.">Yayına al</span><?php endif; ?></form><?php endif; ?></div><ul class="readiness-check"><?php foreach ($readiness['items'] as $item): $copyShort = static fn(string $u): string => basename((string) parse_url($u, PHP_URL_PATH)) . (parse_url($u, PHP_URL_FRAGMENT) !== null ? ' #' . (string) parse_url($u, PHP_URL_FRAGMENT) : ''); $warn = !empty($item['warn']); $cls = !$item['ok'] ? 'missing' : ($warn ? 'warn' : 'ok'); $icon = !$item['ok'] ? '✗' : ($warn ? '⚠' : '✓'); ?><li class="<?= $cls ?>"><?= $icon ?> <?= htmlspecialchars($item['label']) ?><small><?= htmlspecialchars($item['detail']) ?></small><?php if (!$item['ok'] && $item['key'] !== 'rules'): ?> <em class="readiness-gain" title="Bu kalem tamamlanınca hazırlık skoruna eklenir">+<?= (int) ($item['weight'] ?? 0) ?></em><?php endif; ?><?php if (!empty($secHint[$item['key']])): ?> <em class="readiness-sec-hint"><?= htmlspecialchars($secHint[$item['key']]) ?></em><?php endif; ?><?php if (!$item['ok']): ?><a title="<?= htmlspecialchars($linkTooltips[$item['key']] ?? '') ?>" href="<?= htmlspecialchars($linkFor[$item['key']] ?? '#') ?>">Doldur →</a> <span class="ical-copy-row"><code title="<?= htmlspecialchars($linkFor[$item['key']] ?? '#') ?>"><?= htmlspecialchars($copyShort((string) ($linkFor[$item['key']] ?? '#'))) ?></code><button type="button" class="ical-copy-btn" data-copy="<?= htmlspecialchars($linkFor[$item['key']] ?? '#') ?>">Kopyala</button></span><?php elseif ($warn): ?><a title="<?= htmlspecialchars($linkTooltips[$item['key']] ?? '') ?>" href="<?= htmlspecialchars($linkFor[$item['key']] ?? '#') ?>">İncele →</a> <a class="readiness-all-view" title="<?= htmlspecialchars($linkTooltips[$item['key']] ?? '') ?>" href="<?= htmlspecialchars($linkFor[$item['key']] ?? '#') ?>">Gör →</a> <span class="ical-copy-row"><code title="<?= htmlspecialchars($linkFor[$item['key']] ?? '#') ?>"><?= htmlspecialchars($copyShort((string) ($linkFor[$item['key']] ?? '#'))) ?></code><button type="button" class="ical-copy-btn" data-copy="<?= htmlspecialchars($linkFor[$item['key']] ?? '#') ?>">Kopyala</button></span><?php else: ?><a class="readiness-all-view" title="<?= htmlspecialchars($linkTooltips[$item['key']] ?? '') ?>" href="<?= htmlspecialchars($linkFor[$item['key']] ?? '#') ?>">Gör →</a> <span class="ical-copy-row"><code title="<?= htmlspecialchars($linkFor[$item['key']] ?? '#') ?>"><?= htmlspecialchars($copyShort((string) ($linkFor[$item['key']] ?? '#'))) ?></code><button type="button" class="ical-copy-btn" data-copy="<?= htmlspecialchars($linkFor[$item['key']] ?? '#') ?>">Kopyala</button></span><?php if ($item['key'] === 'media' && $item['ok']): $mp = $pdo->prepare("SELECT file_path, is_cover FROM property_media WHERE property_id=? ORDER BY is_cover DESC, sort_order, id LIMIT 8"); $mp->execute([(int) $listing['id']]); $mediaPrev = $mp->fetchAll(); if ($mediaPrev): ?><span class="readiness-media-preview" style="display:flex;flex-wrap:wrap;gap:6px;margin-top:8px;align-items:center"><?php foreach ($mediaPrev as $mediaIdx => $mv): $src = '/nexustraveltech/' . ltrim((string) $mv['file_path'], '/'); ?><span style="position:relative;display:inline-block"><?php if ($mv['is_cover']): ?><span style="position:absolute;left:0;bottom:0;background:#b26a00;color:#fff;font-size:8px;font-weight:700;padding:1px 4px;border-radius:0 4px 0 4px;letter-spacing:.04em;z-index:1">KAPAK</span><?php endif; ?><img src="<?= htmlspecialchars($src) ?>" alt="" loading="lazy" style="width:56px;height:56px;object-fit:cover;border-radius:6px;border:<?= $mv['is_cover'] ? '2px solid #b26a00' : '1px solid #e1e5de' ?>" title="<?= ($mediaIdx+1)?>/<?= count($mediaPrev) ?><?= $mv['is_cover'] ? ' · Kapak' : '' ?>"></span><?php endforeach; ?></span><a class="readiness-media-more" href="<?= htmlspecialchars($linkFor['media'] ?? '#') ?>" style="font-size:11px;color:#4a6d8c;text-decoration:none;border-bottom:1px dotted #4a6d8c">Tümü →</a></span><?php else: ?><span class="readiness-media-empty" style="display:block;margin-top:6px;font-size:12px;color:#8a6100">Görsel yok — ilan görsellerini ekleyin</span><?php endif; endif; endif; ?><?php $icalUrlVisible = empty($item['urls']) ? false : (!(bool) platform_setting('ical_url_published_only', false) || $listing['status'] === 'active'); if ($icalUrlVisible): ?><span class="ical-copy-list"><?php foreach ($item['urls'] as $icalUrl): $icalQ = (string) parse_url($icalUrl, PHP_URL_QUERY); $icalShort = 'api/ical?' . mb_substr($icalQ, 0, 10) . '…' . mb_substr($icalQ, 30, 4) . '…'; ?><span class="ical-copy-row"><code title="<?= htmlspecialchars($icalUrl) ?>"><?= htmlspecialchars($icalShort) ?></code><button type="button" class="ical-copy-btn" data-copy="<?= htmlspecialchars($icalUrl) ?>">Kopyala</button></span><?php endforeach; ?></span><?php endif; ?></li><?php endforeach; ?></ul></section>
