<div class="editor-save"><a href="/nexustraveltech/tedarikci/tesisler">Daha sonra tamamla</a><button type="submit">Tüm detayları kaydet →</button></div></form><script>document.querySelectorAll('.editor-toc nav a').forEach(function(a){a.addEventListener('click',function(e){e.preventDefault();var id=this.getAttribute('href').slice(1),el=document.getElementById(id);if(el){var y=el.getBoundingClientRect().top+window.scrollY-110;window.scrollTo({top:y,behavior:'smooth'})}})});var tocLinks=document.querySelectorAll('.editor-toc nav a'),sections=document.querySelectorAll('.editor-section');function markToc(){var pos=window.scrollY+140,current='';sections.forEach(function(s){if(s.offsetTop<=pos)current=s.id});tocLinks.forEach(function(a){a.classList.toggle('active',a.getAttribute('href')==='#'+current)})}window.addEventListener('scroll',markToc,{passive:true});markToc();if(location.hash){var hEl=document.querySelector(location.hash);if(hEl){setTimeout(function(){var hy=hEl.getBoundingClientRect().top+window.scrollY-110;window.scrollTo({top:hy,behavior:'smooth'})},80)}}function fallbackCopy(text){var ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();try{document.execCommand('copy')}catch(e){}document.body.removeChild(ta)}document.querySelectorAll('.ical-copy-btn').forEach(function(b){if(!b.title)b.title=b.getAttribute('data-copy')||'';b.addEventListener('click',function(){var url=this.getAttribute('data-copy'),btn=this;function done(){btn.textContent='Kopyalandı ✓';btn.classList.add('copied');setTimeout(function(){btn.textContent='Kopyala';btn.classList.remove('copied')},1600)}if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(url).then(done).catch(function(){fallbackCopy(url);done()})}else{fallbackCopy(url);done()}})});</script></div><?php supply_end(); ?>
